def unlink(kind, first, last, nxt, prv, var):
    """The same mutants for the system's two lists."""
    p = "%s->%s" % (var, prv)
    n = "%s->%s" % (var, nxt)
    return [
        ("add %s: prev" % kind, X, "    %s = %s;" % (p, last), "    %s = 0;" % p),
        ("add %s: last's link" % kind, X, "        %s->%s = %s;\n" % (last, nxt, var), ""),
        ("add %s: first" % kind, X, "        %s = %s;\n" % (first, var), ""),
        ("add %s: last" % kind, X, "    %s = %s;\n    %s = 0;" % (last, var, n), "    %s = 0;" % n),
        ("add %s: next kept" % kind, X, "    %s = %s;\n    %s = 0;" % (last, var, n), "    %s = %s;" % (last, var)),
        ("remove %s: prev's link" % kind, X, "        %s->%s = %s;\n" % (p, nxt, n), ""),
        ("remove %s: test" % kind, X, "        if (%s->%s != 0) {" % (p, nxt), "        if (%s->%s == 0) {" % (p, nxt)),
        ("remove %s: next's prev" % kind, X, "            %s->%s = %s;" % (n, prv, p), "            %s->%s = 0;" % (n, prv)),
        ("remove %s: last" % kind, X, "            %s = %s;\n" % (last, p), ""),
        ("remove %s: first" % kind, X, "        %s = %s;\n" % (first, n), ""),
        ("remove %s: new first's prev" % kind, X, "            %s->%s = 0;\n" % (n, prv), ""),
    ]


